-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/pianofollow/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, ROW_H, GAP = 20, 56, 10
local BOX_W = kit.W - 40      -- refreshed in layout(): an app may set kit.W, kit.H for a landscape screen
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  BOX_W = kit.W - 40
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

local __mods, __loaded = {}, {}
local function require(n)
  local v = __loaded[n]
  if v ~= nil then return v end
  local f = __mods[n]
  if not f then error('module not found: ' .. tostring(n)) end
  v = f()
  if v == nil then v = true end
  __loaded[n] = v
  return v
end

__mods['catalog'] = function()
-- catalog: the free pieces, read from the repository's raw files (catalog/piano/ on GitHub), so new
-- pieces appear when they are pushed. The list is kept in catalog.json in the app's folder and still
-- shows offline; pieces are downloaded straight into the folder (request `save`).
--   C.refresh(done)        done(ok, err)
--   C.levels() -> { { level, label, count } }   C.composers(level) -> { name }   C.pieces(level, composer)
--   C.search(text) -> entries;  C.get(id);  C.download(id, done) done(ok, err);  C.installed(id)
local S = require('score')
local C = {}
C.BASE = 'https://raw.githubusercontent.com/omer-faruq-xteink/touch-licorice-apps/main/catalog/piano/'
local LEVELS = { 'beginner', 'easy', 'intermediate', 'advanced' }
local LABEL = { beginner = 'Beginner', easy = 'Easy', intermediate = 'Intermediate', advanced = 'Advanced' }
local data = nil

local function load_cached()
  local ok, s = pcall(function() return ctx.files:read('catalog.json', 0, 65536) end)
  if not ok or type(s) ~= 'string' or s == '' then return false end
  -- a catalog longer than one read
  local parts, off = { s }, #s
  while #parts[#parts] == 65536 do
    local more = ctx.files:read('catalog.json', off, 65536)
    if not more or more == '' then break end
    parts[#parts + 1] = more
    off = off + #more
  end
  local ok2, d = pcall(function() return ctx.json:decode(table.concat(parts)) end)
  if ok2 and type(d) == 'table' and type(d.pieces) == 'table' then data = d; return true end
  return false
end

function C.refresh(done)
  C.rescan()
  local job, err = ctx.net:request({ url = C.BASE .. 'catalog.json', save = { to = 'files', name = 'catalog.json' } }, function(_c, res)
    local fresh = res.ok and res.status == 200 and res.saved and load_cached()
    if fresh then done(true) return end
    load_cached()
    done(false, (not res.ok) and (res.err == 'no_network' and 'No connection' or tostring(res.err or 'error'))
      or ('the catalog answered ' .. tostring(res.status)))
  end)
  if not job then load_cached(); done(false, err == 'busy' and 'busy, try again' or tostring(err)) end
end

function C.loaded() return data ~= nil end

function C.levels()
  local out = {}
  if not data then return out end
  for _k, lv in ipairs(LEVELS) do
    local n = 0
    for _j, p in ipairs(data.pieces) do if p.level == lv then n = n + 1 end end
    if n > 0 then out[#out + 1] = { level = lv, label = LABEL[lv], count = n } end
  end
  return out
end

function C.composers(level)
  local seen, out = {}, {}
  for _k, p in ipairs(data and data.pieces or {}) do
    if p.level == level and not seen[p.composer] then seen[p.composer] = true; out[#out + 1] = p.composer end
  end
  table.sort(out, function(a, b) return a:lower() < b:lower() end)
  return out
end

local function by_title(t) table.sort(t, function(a, b) return a.title:lower() < b.title:lower() end) return t end

function C.pieces(level, composer)
  local out = {}
  for _k, p in ipairs(data and data.pieces or {}) do
    if p.level == level and p.composer == composer then out[#out + 1] = p end
  end
  return by_title(out)
end

function C.search(text)
  local q, out = (text or ''):lower(), {}
  if q == '' then return out end
  for _k, p in ipairs(data and data.pieces or {}) do
    if p.title:lower():find(q, 1, true) or (p.composer or ''):lower():find(q, 1, true) then out[#out + 1] = p end
  end
  return by_title(out)
end

function C.get(id)
  for _k, p in ipairs(data and data.pieces or {}) do if p.id == id then return p end end
  return nil
end

local function file_of(id) return id .. '.xtscore' end
-- which pieces are on the reader: one listing of the folder, not a card read per catalog entry
local have = nil
function C.rescan()
  have = {}
  local ok, files = pcall(function() return ctx.files:list() end)
  if ok and type(files) == 'table' then for _k, f in ipairs(files) do have[f.name:lower()] = true end end
end
function C.installed(id)
  if not have then C.rescan() end
  return have[file_of(id):lower()] == true
end
function C.file(id) return file_of(id) end

function C.download(id, done)
  local name = file_of(id)
  local job, err = ctx.net:request({ url = C.BASE .. 'pieces/' .. name, save = { to = 'files', name = name } }, function(_c, res)
    if not (res.ok and res.status == 200 and res.saved) then
      done(false, (not res.ok) and (res.err == 'no_network' and 'No connection' or tostring(res.err)) or ('download failed (' .. tostring(res.status) .. ')'))
      return
    end
    if not S.open(name) then
      pcall(function() ctx.files:remove(name) end)
      done(false, 'the download is damaged, try again later')
      return
    end
    C.rescan()
    done(true)
  end)
  if not job then done(false, err == 'busy' and 'busy, try again' or tostring(err)) end
end

return C
end

__mods['follow'] = function()
-- follow: where the player is in the piece, from the notes they play (Page turn and Follow modes).
--   F.new(map, page, turn_at) -> st      turn_at 'end' (the page's last note, the default), 'bar' (its last
--                                        bar) or 'system' (its last system)
--   F.note(st, pitch, now_ms) -> 'turn' | 'bar' | nil    ('turn' has already set st.page)
--   F.goto_page(st, page)                a page turned by hand
--   st.pos = the next expected onset (1-based), st.bar = the bar of the last matched onset, st.page
-- A note of the expected onset moves on. Any other note asks where the last notes played fit best in
-- the bars around the position (the same chord or the onset before, note by note): the position moves
-- only when at least three notes fit, and on a tie back wins over ahead, since a player who repeats a
-- bar must not be taken for one who is ahead. After four notes that fit nowhere near, the whole piece is
-- searched. A page turns only after two expected onsets in a row at its turn point: a late turn is fine,
-- an early one is not.
local F = {}
local LOST, RECENT, NEAR_BACK, NEAR_AHEAD = 4, 5, 16, 8
-- a chord's notes come within a few ms of each other: one that belongs to the onset just completed is
-- part of that chord
local CHORD_MS = 100

local function has(o, p)
  for _k, q in ipairs(o[6]) do if q == p then return true end end
  for _k, q in ipairs(o[7]) do if q == p then return true end end
  return false
end
local function size(o) return #o[6] + #o[7] end

-- the onset where a visit to `page` starts: the visit nearest `near` (ahead preferred), so that a page
-- turned by hand during a written repeat keeps the player in the pass they are in
local function start_of_page(map, page, near)
  local best, bestd
  for i, o in ipairs(map.onsets) do
    if o[3] == page and (i == 1 or map.onsets[i - 1][3] ~= page) then
      local d = i - (near or 1)
      d = d >= 0 and d or -3 * d
      if not best or d < bestd then best, bestd = i, d end
    end
  end
  if best then return best end
  for i, o in ipairs(map.onsets) do if o[3] >= page then return i end end
  return #map.onsets + 1
end

function F.new(map, page, turn_at)
  local st = { map = map, n = #map.onsets, page = page or 1, turn_at = turn_at or 'end', run = 0, miss = 0,
               hits = {}, recent = {}, bar = nil }
  st.pos = start_of_page(map, st.page, 1)
  return st
end

function F.goto_page(st, page)
  st.page = math.max(1, math.min(#st.map.turn, page))
  st.pos = start_of_page(st.map, st.page, st.pos)
  st.run, st.miss, st.hits, st.exit = 0, 0, {}, nil
end

-- where the playing (repeats unfolded) next leaves the shown page: the first onset after i on another
-- page; the page turns in the bar before that (the page's last bar, or the bar before a repeat), to the
-- page the music continues on (back a page at a repeat)
local function exit_after(st, i)
  for j = i + 1, st.n do if st.map.onsets[j][3] ~= st.page then return j end end
  return nil
end

-- after an expected onset: a turn when confidently at the turn point, else a new bar
local function after_advance(st)
  local i = st.pos - 1
  local o = st.map.onsets[i]
  if st.exit and i >= st.exit then st.exit = nil end  -- past the onset the early turn was for
  if st.run >= 2 and not st.exit then
    if o[3] ~= st.page then                          -- the music is on another page: show it
      st.page, st.bar = o[3], o[2]
      return 'turn'
    end
    local j = exit_after(st, i)
    if j then
      local tb = st.map.onsets[j - 1][2]              -- the last bar played on this page
      local t = st.map.turn[st.page]
      if st.turn_at == 'system' and t and st.map.onsets[t[1]] and st.map.onsets[t[2]] and tb >= st.map.onsets[t[2]][2] then
        tb = st.map.onsets[t[1]][2]                   -- leaving at the page's end: from its last system
      end
      local at = st.turn_at == 'end' and i >= j - 1 or st.turn_at ~= 'end' and o[2] >= tb
      if at then                                      -- turned while the bar is still played: finish it here
        st.page, st.bar, st.exit = st.map.onsets[j][3], o[2], j
        return 'turn'
      end
    end
  end
  if o[2] ~= st.bar then st.bar = o[2]; return 'bar' end
  return nil
end

-- the last notes played, walking back from onset j: each earlier note must be in the same onset (a
-- chord) or the one before
local function fits(st, j)
  local k, count, span = j, 0, 1
  for r = #st.recent, 1, -1 do
    local p = st.recent[r]
    local o = st.map.onsets[k]
    if o and has(o, p) then count = count + 1
    elseif k > 1 and has(st.map.onsets[k - 1], p) then k = k - 1; span = span + 1; count = count + 1
    else break end
  end
  return count >= 3 and span >= 2, count
end

-- the best fit for the recent notes among onsets lo..hi: near the position, most notes first, then the
-- smallest move (a move back counting as smaller than the same move ahead); in the whole piece
-- (`nearest`), the smallest move that fits, since an exact repeat far away fits as well as the truth.
-- Never on an earlier page: written repeats come from the playing order, and a player who goes back a
-- page on purpose turns it by hand (an exact repeat elsewhere would otherwise turn the page back).
local function best_fit(st, lo, hi, nearest)
  local best, bestc, bestd
  for j = math.max(2, lo), math.min(st.n, hi) do
    local ok, c = fits(st, j)
    if nearest and c < 4 then ok = false end          -- the whole piece: four notes, not three
    if ok and st.map.onsets[j][3] < st.page then ok = false end   -- never back a page by guessing
    if ok then
      local d = j + 1 - st.pos
      d = d >= 0 and d * 2 or -d
      local better = not best or (nearest and d < bestd) or (not nearest and (c > bestc or (c == bestc and d < bestd)))
      if better then best, bestc, bestd = j, c, d end
    end
  end
  return best
end

-- the position moves to just after onset j (never an earlier page, see best_fit); a later page is shown
-- only after expected onsets confirm it
local function move_to(st, j)
  -- ahead, three notes in order are as good as two clean onsets; back (a repeat) starts from nothing
  local ahead = j + 1 > st.pos
  st.pos, st.run, st.miss, st.hits, st.exit = j + 1, ahead and 2 or 0, 0, {}, nil
  st.bar = st.map.onsets[j][2]
  local pg = st.map.onsets[j][3]
  return pg == st.page and 'bar' or nil
end

function F.note(st, pitch, now_ms)
  st.recent[#st.recent + 1] = pitch
  if #st.recent > RECENT then table.remove(st.recent, 1) end
  local last = st.map.onsets[st.pos - 1]
  if last and st.done_t and now_ms and now_ms - st.done_t <= CHORD_MS and has(last, pitch) then
    return nil                                       -- the rest of the chord just played
  end
  local cur = st.map.onsets[st.pos]
  if cur and has(cur, pitch) then                    -- the expected onset
    st.miss = 0
    local h = st.hits[st.pos] or {}
    h[pitch] = true
    st.hits[st.pos] = h
    local n = 0
    for _p in pairs(h) do n = n + 1 end
    if n < math.ceil(size(cur) / 2) then return nil end
    st.run = st.run + 1
    st.pos, st.done_t = st.pos + 1, now_ms
    st.hits[st.pos] = nil
    return after_advance(st)
  end
  -- not the expected onset: where do the last notes fit nearby?
  local j = best_fit(st, st.pos - NEAR_BACK, st.pos + NEAR_AHEAD)
  if j and j + 1 == st.pos then st.miss = 0; return nil end   -- explained where we are (a rolled chord)
  if not j and st.pos > 1 and has(st.map.onsets[st.pos - 1], pitch) then return nil end   -- the last onset again
  if j then return move_to(st, j) end
  st.run = 0                                         -- a slip: the next turn waits for two clean onsets
  st.miss = st.miss + 1
  if st.miss >= LOST then                            -- nothing near fits: the whole piece
    local g = best_fit(st, 2, st.n, true)
    st.miss = 0
    if g and g + 1 ~= st.pos then return move_to(st, g) end
  end
  return nil
end

return F
end

__mods['kbd'] = function()
-- kbd: the Bluetooth MIDI keyboard (BLE central: scan, connect, subscribe, reconnect).
--   K.start(on_note, on_state)   on_note(ev) per parsed note (midi.lua); on_state() when the state changes
--   K.scan(), K.pick(i), K.forget(), K.devices() -> found list, K.state(), K.name(), K.last()
--   states: 'off' (no Bluetooth), 'none', 'scanning', 'connecting', 'connected', 'lost'
-- The keyboard is remembered in kbd.txt (address, address type, name, secure 0/1) and connected
-- straight away next time. A keyboard that refuses the subscription is tried again with pairing
-- (secure = true), which is then remembered. A lost keyboard is tried again every 5 s, 12 times.
local M = require('midi')
local K = {}
local SVC, CHR = '03b80e5a-ede8-4b33-a751-6ce34ec4c700', '7772e5db-3868-4112-a1a9-f2669d106bf3'
local RETRY_MS, RETRIES, FILE = 5000, 12, 'kbd.txt'

local state, dev, conn, found, last = 'none', nil, nil, {}, nil
local on_note, on_state = function() end, function() end
local tries, parser = 0, M.new()

local function set(s) if s ~= state then state = s; on_state() end end
local function ble() return ctx.ble end

local function remember(d)
  kit.write(FILE, table.concat({ d.address, d.address_type or 'public', d.name or '', d.secure and '1' or '0', '' }, '\n'))
end
local function recall()
  local s = kit.read(FILE)
  if not s or s == '' then return nil end
  local a, t, n, sec = s:match('^([^\n]*)\n([^\n]*)\n([^\n]*)\n?([01]?)')
  if not a or a == '' then return nil end
  return { address = a, address_type = t, name = n, secure = sec == '1' }
end

local connect

local function retry_later(ms, fn) ctx:after(ms, function() fn() end) end

local function lost()
  conn = nil
  if tries >= RETRIES then set('none'); return end
  tries = tries + 1
  set('lost')
  retry_later(RETRY_MS, function() if state == 'lost' and dev then connect() end end)
end

-- the connection in progress or open (K._mine); a new one first closes it, and the callbacks of an
-- older one do nothing (they would save the wrong keyboard or mark the new one lost)
local function drop_current()
  local m = K._mine
  K._mine = nil
  if m then
    m.closing = true
    if m.conn then pcall(function() m.conn:close() end) end
  end
  conn = nil
end

local busy_tries = 0
connect = function()
  if not dev or not ble() then return end
  drop_current()
  set(state == 'lost' and 'lost' or 'connecting')
  parser = M.new()
  local d = dev                                       -- the keyboard this connection is for
  local mine = { closing = false }
  local function current() return K._mine == mine and not mine.closing end
  local c, err = ble():connect({ address = d.address, address_type = d.address_type, timeout_ms = 10000, secure = d.secure or false }, {
    on_connect = function(_c, cn)
      if not current() then return end
      if not cn then lost(); return end
      cn:subscribe(CHR, true, function(_c2, cn2, e)
        if not current() then return end
        if e then
          mine.closing = true
          pcall(function() cn2:close() end)
          conn = nil
          if not d.secure then                              -- maybe it wants pairing: once more, secure
            d.secure = true
            retry_later(300, connect)
          else
            lost()
          end
          return
        end
        tries, busy_tries = 0, 0
        conn = cn2
        remember(d)
        set('connected')
      end)
    end,
    on_notify = function(_c, _cn, _h, data)
      if not current() then return end
      for _k, ev in ipairs(M.feed(parser, data)) do
        if ev.on then last = ev.note end
        pcall(on_note, ev)                              -- a fault in the score must not end the session
      end
    end,
    on_disconnect = function(_c, _cn, e)
      if not current() or e == nil then return end      -- an older connection, or our own close
      lost()
    end,
  })
  if not c then
    if err == 'busy' and busy_tries < 15 then busy_tries = busy_tries + 1; retry_later(200, connect)
    else busy_tries = 0; lost() end
    return
  end
  mine.conn = c
  K._mine = mine
end

-- search for BLE MIDI keyboards; the remembered one is connected as soon as it is seen, and if the
-- search ends without it, it is tried directly once
local function look()
  if not ble() then return end
  found = {}
  local s, err
  s, err = ble():scan({ duration_ms = 8000, services = { SVC } }, {
    on_device = function(_c, sc, d)
      found[#found + 1] = d
      if dev and not conn and state == 'scanning' and d.address == dev.address then
        dev.address_type = d.address_type or dev.address_type
        pcall(function() sc:stop() end)
        tries = 0
        connect()
      end
      on_state()
    end,
    on_done = function(_c, _s, _devs, _e)
      if state == 'scanning' then
        if dev and not conn then tries = 0; connect() else set(conn and 'connected' or 'none') end
      end
      on_state()
    end,
  })
  if s then set('scanning') elseif err then set('none') end
end

function K.start(note_fn, state_fn)
  on_note, on_state = note_fn or on_note, state_fn or on_state
  if not ble() then state = 'off'; return end
  dev = recall()
  if dev then look() else state = 'none' end
end

function K.scan() if state ~= 'connecting' then look() end end

-- the Keyboard screen opened: search unless connected or already at it
function K.auto()
  if ble() and state ~= 'connected' and state ~= 'connecting' and state ~= 'scanning' then look() end
end

function K.pick(i)
  local d = found[i]
  if not d or state == 'connecting' then return end      -- one connection at a time
  dev = { address = d.address, address_type = d.address_type, name = d.name or d.address, secure = false }
  tries = 0
  connect()
end

function K.forget()
  drop_current()
  dev = nil
  pcall(function() ctx.storage:remove(FILE) end)
  kit.write(FILE, '')
  set(ble() and 'none' or 'off')
end

function K.devices() return found end
function K.state() return state end
function K.name() return dev and dev.name or nil end
function K.last() return last end

return K
end

__mods['midi'] = function()
-- midi: BLE MIDI packets (the notify value of the BLE MIDI characteristic) -> note events.
--   packet = header (bit 7 set, timestamp bits 12-7), then messages, each preceded by a timestamp
--   byte (bit 7 set, bits 6-0) or, with running status, by nothing; SysEx may span packets.
--   M.new() -> parser;  M.feed(parser, packet) -> { { on = bool, note, vel, ts }, ... }
-- Any channel; note-on with velocity 0 is a note-off; everything that is not a note is skipped.
local M = {}

function M.new() return { running = nil, sysex = false } end

local function data_len(s)
  local hi = s & 0xF0
  if hi == 0xC0 or hi == 0xD0 then return 1 end
  if s < 0xF0 then return 2 end
  if s == 0xF1 or s == 0xF3 then return 1 end
  if s == 0xF2 then return 2 end
  return 0
end

function M.feed(st, pkt)
  local out = {}
  local n = #pkt
  if n < 2 then return out end
  local hdr = pkt:byte(1)
  if hdr < 0x80 then return out end
  local hi, ts, i = hdr & 0x3F, 0, 2
  while i <= n do
    local b = pkt:byte(i)
    if st.sysex then
      -- inside SysEx: data bytes until (timestamp) F7; a timestamp before anything else ends it too
      if b < 0x80 then i = i + 1
      elseif b == 0xF7 then st.sysex = false; i = i + 1
      elseif pkt:byte(i + 1) == 0xF7 then st.sysex = false; i = i + 2
      elseif (pkt:byte(i + 1) or 0) >= 0xF8 then i = i + 2          -- realtime inside SysEx
      else st.sysex = false end
    else
      if b >= 0x80 then                                             -- timestamp byte
        ts = (hi << 7) | (b & 0x7F)
        i = i + 1
        b = pkt:byte(i)
        if not b then break end
        if b >= 0x80 then                                           -- a status byte
          i = i + 1
          if b == 0xF0 then st.sysex = true; st.running = nil; goto continue end
          if b >= 0xF8 then goto continue end                      -- realtime: running status stays
          if b >= 0xF0 then st.running = nil; i = i + data_len(b); goto continue end
          st.running = b
          b = pkt:byte(i)
          if not b or b >= 0x80 then goto continue end
        end
      end
      -- data bytes of the running status
      local s = st.running
      if not s then i = i + 1; goto continue end
      local need = data_len(s)
      local d1, d2 = pkt:byte(i), need == 2 and pkt:byte(i + 1) or 0
      if not d1 or d1 >= 0x80 or not d2 or d2 >= 0x80 then i = i + 1; goto continue end
      i = i + need
      local kind = s & 0xF0
      if kind == 0x90 then out[#out + 1] = { on = d2 > 0, note = d1, vel = d2, ts = ts }
      elseif kind == 0x80 then out[#out + 1] = { on = false, note = d1, vel = d2, ts = ts } end
    end
    ::continue::
  end
  return out
end

return M
end

__mods['practice'] = function()
-- practice: the score waits for the right notes (Practice mode).
--   P.new(map, hands, from_onset) -> st       hands 'r', 'l' or 'b' (both)
--   P.note_on(st, pitch, now_ms) -> 'advance' | 'wrong' | nil;  P.note_off(st, pitch)
--   st.pos (the onset waited for), st.wrong (count), st.done;  P.summary(st) -> { wrong, bars = { { bar, wrong } } }
-- An onset is played when each of its notes for the chosen hand(s) was pressed after it became the
-- one waited for and is still held or was pressed within the last second (a chord in any order).
-- Onsets with nothing for the chosen hand(s) are skipped. A note that is in none of the onsets from
-- the one before the last step to this one (the other hand's notes while this hand rests) is a mistake,
-- counted for the bar.
local P = {}
local CHORD_MS = 1000

local function required(st, i)
  local o = st.map.onsets[i]
  local t = {}
  if st.hands ~= 'l' then for _k, p in ipairs(o[6]) do t[#t + 1] = p end end
  if st.hands ~= 'r' then for _k, p in ipairs(o[7]) do t[#t + 1] = p end end
  return t
end

local function in_onset(st, i, p)
  local o = st.map.onsets[i]
  if not o then return false end
  for _k, q in ipairs(o[6]) do if q == p then return true end end
  for _k, q in ipairs(o[7]) do if q == p then return true end end
  return false
end

-- the first onset from i on with something to play for the chosen hand(s); `from` remembers where the
-- skipped onsets begin, so the other hand's notes in them are not mistakes
local function settle(st, i, now)
  st.from = i
  while i <= #st.map.onsets and #required(st, i) == 0 do i = i + 1 end
  st.pos = i
  st.start = now or st.start or 0
  st.done = i > #st.map.onsets
end

function P.new(map, hands, from_onset)
  local st = { map = map, hands = hands or 'b', wrong = 0, per_bar = {}, pressed = {}, held = {}, start = -math.huge }
  settle(st, from_onset or 1, -math.huge)
  return st
end

function P.note_off(st, pitch) st.held[pitch] = nil end

function P.note_on(st, pitch, now)
  st.pressed[pitch], st.held[pitch] = now, true
  if st.done then return nil end
  local excused = false
  for k = math.max(1, math.min(st.from or st.pos, st.pos) - 1), st.pos do
    if in_onset(st, k, pitch) then excused = true; break end
  end
  if not excused then
    st.wrong = st.wrong + 1
    local bar = st.map.onsets[st.pos][2]
    st.per_bar[bar] = (st.per_bar[bar] or 0) + 1
    return 'wrong'
  end
  for _k, p in ipairs(required(st, st.pos)) do
    local t = st.pressed[p]
    if not t or t < st.start or not (st.held[p] or now - t <= CHORD_MS) then return nil end
  end
  settle(st, st.pos + 1, now)
  return 'advance'
end

function P.summary(st)
  local bars = {}
  for bar, n in pairs(st.per_bar) do bars[#bars + 1] = { bar = bar, wrong = n } end
  table.sort(bars, function(a, b) return a.bar < b.bar end)
  return { wrong = st.wrong, bars = bars }
end

return P
end

__mods['score'] = function()
-- score: reading .xtscore files from the app's folder (AppFiles/pianofollow/).
--   "XTSCORE1", uint32 LE header length N, N bytes of JSON header, then zlib streams
--   (pages of 760 rows x 60 bytes, and the note map as JSON). See site/tools/piano/convert.mjs.
--
--   S.open(name) -> piece | nil, 'not_found' | 'bad_file'     piece = { name, header, size }
--   S.page_bits(piece, i) -> h * w/8 bytes (header w, h) | nil, err
--   S.load_map(piece) -> map | nil, err                        (kept in piece.map)
--   S.list() -> { { name, title, composer, level, size, bad } } sorted by title
local S = {}
local MAGIC, CHUNK = 'XTSCORE1', 65536

local function read(name, off, len)
  local ok, d, e = pcall(function() return ctx.files:read(name, off, len) end)
  if not ok then return nil, 'bad_file' end
  return d, e
end

-- a range longer than one read (the note map of a long piece)
local function read_all(name, off, len)
  local parts, got = {}, 0
  while got < len do
    local d = read(name, off + got, math.min(CHUNK, len - got))
    if not d or #d == 0 then return nil end
    parts[#parts + 1] = d
    got = got + #d
  end
  return table.concat(parts)
end

local function valid_range(r, size)
  return type(r) == 'table' and type(r[1]) == 'number' and type(r[2]) == 'number'
    and r[1] >= 12 and r[2] > 0 and r[1] + r[2] <= size
end

function S.open(name)
  local head, err = read(name, 0, 12)
  if not head then return nil, err == 'not_found' and 'not_found' or 'bad_file' end
  if #head < 12 or head:sub(1, 8) ~= MAGIC then return nil, 'bad_file' end
  local n = string.unpack('<I4', head, 9)
  if n < 2 or n > CHUNK then return nil, 'bad_file' end
  local hj = read(name, 12, n)
  if not hj or #hj < n then return nil, 'bad_file' end
  local ok, h = pcall(function() return ctx.json:decode(hj) end)
  if not ok or type(h) ~= 'table' or type(h.pages) ~= 'table' or #h.pages == 0 then return nil, 'bad_file' end
  local size = ctx.files:size(name) or 0
  for _k, r in ipairs(h.pages) do if not valid_range(r, size) or r[2] >= CHUNK then return nil, 'bad_file' end end
  if not valid_range(h.map, size) then return nil, 'bad_file' end
  -- the page size: 480 x 760 upright, 800 x 440 turned
  if math.type(h.w) ~= 'integer' or math.type(h.h) ~= 'integer' or h.w % 8 ~= 0 or h.w < 8 or h.h < 8 or h.w > 800 or h.h > 800 then return nil, 'bad_file' end
  if type(h.title) ~= 'string' or h.title == '' then h.title = name:gsub('%.[^.]*$', '') end
  return { name = name, header = h, size = size }
end

function S.page_bits(p, i)
  local r = p.header.pages[i]
  if not r then return nil, 'invalid_argument' end
  local z = read(p.name, r[1], r[2])
  if not z or #z < r[2] then return nil, 'bad_file' end
  pcall(function() ctx.budget:extend() end)
  local ok, bits = pcall(function() return ctx.zlib:decompress(z, { format = 'zlib' }) end)
  if not ok or type(bits) ~= 'string' or #bits ~= p.header.h * (p.header.w // 8) then return nil, 'bad_file' end
  return bits
end

function S.load_map(p)
  if p.map then return p.map end
  pcall(function() ctx.budget:extend() end)
  local r = p.header.map
  local z = read_all(p.name, r[1], r[2])
  if not z then return nil, 'bad_file' end
  local ok, js = pcall(function() return ctx.zlib:decompress(z, { format = 'zlib' }) end)
  if not ok or type(js) ~= 'string' then return nil, 'bad_file' end
  local ok2, m = pcall(function() return ctx.json:decode(js) end)
  if not ok2 or type(m) ~= 'table' or type(m.onsets) ~= 'table' or type(m.bars) ~= 'table' or type(m.turn) ~= 'table' then
    return nil, 'bad_file'
  end
  p.map = m
  return m
end

-- My pieces. Opening every file on each visit would cost three card reads a piece (the callback limit
-- is 1000 ms), so a private index keeps name, size, title, composer and level; only new or changed files
-- are opened.
local INDEX = 'pieces.txt'
local function clean(v) return (tostring(v or ''):gsub('[%c]', ' ')) end   -- no tabs or line breaks in the index

function S.list()
  pcall(function() ctx.budget:extend() end)
  local ok, files = pcall(function() return ctx.files:list() end)
  local out = {}
  if not ok or type(files) ~= 'table' then return out end
  local cache = {}
  for line in (kit.read(INDEX) or ''):gmatch('[^\n]+') do
    local name, size, title, composer, level, bad = line:match('^([^\t]*)\t(%d+)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([01])$')
    if name then cache[name] = { name = name, size = tonumber(size), title = title, composer = composer, level = level, bad = bad == '1' or nil } end
  end
  local changed, opened = false, 0
  for _k, f in ipairs(files) do
    if f.name:lower():match('%.xtscore$') then
      local row = cache[f.name]
      if not row or row.size ~= f.size then
        opened = opened + 1
        if opened % 5 == 0 then pcall(function() ctx.budget:extend() end) end
        local p = S.open(f.name)
        if p then
          row = { name = f.name, title = clean(p.header.title), composer = clean(p.header.composer), level = clean(p.header.level), size = f.size }
        else
          row = { name = f.name, title = clean(f.name), composer = '', level = '', size = f.size, bad = true }
        end
        changed = true
      end
      out[#out + 1] = row
    end
  end
  if changed or #out ~= (function() local n = 0 for _ in pairs(cache) do n = n + 1 end return n end)() then
    local lines = {}
    for _k, r in ipairs(out) do
      lines[#lines + 1] = table.concat({ r.name, r.size, r.title, r.composer, r.level, r.bad and '1' or '0' }, '\t')
    end
    kit.write(INDEX, table.concat(lines, '\n'))
  end
  table.sort(out, function(a, b) return a.title:lower() < b.title:lower() end)
  return out
end

return S
end

-- Piano Follow: sheet music that follows your playing (see apps/pianofollow/README.md).
-- Screens: home (My pieces), score (one page at a time, three modes), summary (after practice).
-- Modules: score (files), midi (BLE MIDI packets), follow (Page turn / Follow), practice.
local S = require('score')
local M = require('midi')
local F = require('follow')
local P = require('practice')
local K = require('kbd')
local C = require('catalog')
-- the whole app runs in landscape (manifest display.orientation): 800 x 480, pages of 800 x 440
kit.W, kit.H = 800, 480
local W, H = kit.W, kit.H
local BAR_H = 40
local function SW() return W end
local ERR = nil

local screen = 'home'
local pieces = {}            -- home list (S.list rows)
local cur = nil              -- the open piece: { p, name, page, pages, map, mode, hands, fst, pst }
local layer, layer_page = nil, nil
local settings = { turn_at = 'end' }   -- 'end': on the page's last note; 'bar' / 'system': earlier
local home_page = 1           -- the page of the My pieces list
local go_home                -- defined with the pieces below

local MODE_NAME = { turn = 'Page turn', follow = 'Follow', practice = 'Practice' }
local HAND_NAME = { r = 'right', l = 'left', b = 'both' }

local function small() return kit.font('small') end
local function medium() return kit.font('medium') end
local function now() return kit.now_ms() or 0 end

------------------------------------------------------------------ redraws

-- e-ink frames cost about half a second: markers are redrawn at most every `delay` ms
local last_ref, timer = -math.huge, nil
local function refresh_now()
  if timer then timer:cancel(); timer = nil end
  last_ref = now()
  kit.refresh()
end
local function request(delay)
  if timer then return end
  local wait = delay - (now() - last_ref)
  if wait <= 0 then refresh_now(); return end
  timer = ctx:after(wait, function() timer = nil; last_ref = now(); kit.refresh() end)
end

------------------------------------------------------------------ pieces and pages

-- the private file of a piece's mode, hands and page: private names allow only [a-z0-9._-] (64 bytes),
-- so it is named after a hash of the piece's file name
local function piece_key(name)
  local h = 5381
  for i = 1, #name do h = (h * 33 + name:byte(i)) & 0x7fffffff end
  return string.format('p-%08x.txt', h)
end

local function save_piece()
  if not cur then return end
  kit.write(piece_key(cur.name), 'mode=' .. cur.mode .. '\nhands=' .. cur.hands .. '\npage=' .. cur.page .. '\n')
end

-- the page goes into one offscreen layer, written from the file's bitmap
local function show_page(n)
  if not cur then return end
  n = math.max(1, math.min(cur.pages, n))
  cur.page = n
  if layer_page == n then return end
  local hw, hh = cur.p.header.w, cur.p.header.h
  if layer and (layer.width ~= hw or layer.height ~= hh) then layer:release(); layer = nil end
  if not layer then layer = ctx.layers:create(hw, hh) end
  local bits, err = S.page_bits(cur.p, n)
  if not bits then ERR = 'page ' .. n .. ': ' .. tostring(err); return end
  layer:set_bits(bits, 0)
  layer_page = n
end

local function first_onset_of(field, value)
  for i, o in ipairs(cur.map.onsets) do if o[field] >= value then return i end end
  return #cur.map.onsets
end

-- (re)start the follower or the practice for the current mode, from the shown page (or an onset)
local function start_mode(from_onset)
  cur.fst, cur.pst = nil, nil
  if not cur.map then return end
  if cur.mode == 'practice' then
    cur.pst = P.new(cur.map, cur.hands, from_onset or first_onset_of(3, cur.page))
    local o = cur.map.onsets[cur.pst.pos]
    if o then show_page(o[3]) end
  else
    cur.fst = F.new(cur.map, cur.page, settings.turn_at)
  end
end

local function msg_box(title, line)
  kit.show({ title = title, lines = { line }, rows = { { { 'OK', kit.close } } }, cancel = kit.close })
end

local function open_piece(row)
  if row.bad then msg_box("Can't open this file", row.name .. ': it is not a Piano Follow score, or it is damaged.'); return end
  local p, err = S.open(row.name)
  if not p then msg_box("Can't open this file", row.name .. ': ' .. tostring(err)); return end
  if p.header.w > W or p.header.h > H - BAR_H then
    msg_box("Can't open this file", row.name .. ' was made for an upright screen by an older converter: convert it again.')
    return
  end
  local kv = kit.kv(kit.read(piece_key(row.name)))
  cur = { p = p, name = row.name, page = 1, pages = #p.header.pages,
          mode = MODE_NAME[kv.mode or ''] and kv.mode or 'turn', hands = HAND_NAME[kv.hands or ''] and kv.hands or 'b' }
  local map = S.load_map(p)
  if map then cur.map = map else ERR = 'no note map: page turning by hand only' end
  layer_page = nil
  screen = 'score'
  show_page(tonumber(kv.page) or 1)
  start_mode()
end

go_home = function()
  if cur then save_piece() end
  screen, cur, layer_page = 'home', nil, nil
  pieces = S.list()
  local per = 2 * ((H - 80 - 110) // 56)                -- as PER_PAGE below
  home_page = math.min(home_page, math.max(1, (#pieces + per - 1) // per))
end

local function turn_by_hand(n)
  local before = cur.page
  show_page(n)
  if cur.page ~= before then
    if cur.fst then F.goto_page(cur.fst, cur.page) end
    save_piece()
  end
end

------------------------------------------------------------------ notes from the keyboard

-- one parsed note event { on, note, vel, ts } (kbd.lua calls this)
function on_midi(ev)
  if screen ~= 'score' or not cur or not cur.map then return end
  if cur.mode == 'practice' then
    local st = cur.pst
    if not ev.on then P.note_off(st, ev.note); return end
    local r = P.note_on(st, ev.note, now())
    if r == 'advance' then
      if st.done then screen = 'summary'; refresh_now(); return end
      local pg = cur.map.onsets[st.pos][3]
      if pg ~= cur.page then show_page(pg); save_piece(); refresh_now(); return end
      request(300)
    elseif r == 'wrong' then
      request(300)
    end
    return
  end
  if not ev.on then return end
  local e = F.note(cur.fst, ev.note, now())
  if e == 'turn' then
    show_page(cur.fst.page)
    save_piece()
    refresh_now()
  elseif e == 'bar' and cur.mode == 'follow' then
    request(1000)
  end
end

------------------------------------------------------------------ menus

local function mode_label()
  if not cur then return nil end
  if cur.mode == 'practice' then return 'Practice: ' .. HAND_NAME[cur.hands] end
  return MODE_NAME[cur.mode]
end
local MODE_W = 160
local function MODE_X() return math.floor((SW() - MODE_W) / 2) end

local function set_mode(m, hands)
  kit.close()
  cur.mode = m
  if hands then cur.hands = hands end
  start_mode()
  save_piece()
end

local function delete_piece()
  kit.show({ title = 'Delete this piece?', lines = { cur.p.header.title }, rows = { {
    { 'Delete', function()
        kit.close()
        local name = cur.name
        pcall(function() ctx.files:remove(name) end)
        C.rescan()
        pcall(function() ctx.storage:remove(piece_key(name)) end)
        cur = nil
        go_home()
      end },
    { 'Cancel', kit.close } } }, cancel = kit.close })
end

local function mode_menu()
  if not cur.map then
    kit.show({ title = 'No note map', lines = { 'This file only has its pages: turn them by hand.' },
               rows = { { { 'OK', kit.close } }, { { 'Delete this piece', delete_piece } } }, cancel = kit.close })
    return
  end
  kit.show({ title = 'Mode', rows = {
    { { 'Delete this piece', delete_piece } },
    { { 'Page turn', function() set_mode('turn') end } },
    { { 'Follow', function() set_mode('follow') end } },
    { { 'Practice', function()
        kit.show({ title = 'Practice with', rows = {
          { { 'Right hand', function() set_mode('practice', 'r') end } },
          { { 'Left hand', function() set_mode('practice', 'l') end } },
          { { 'Both hands', function() set_mode('practice', 'b') end } } }, cancel = kit.close })
      end } } }, cancel = kit.close })
end

------------------------------------------------------------------ drawing

local ROW_Y, ROW_H = 110, 56
-- lists: two columns of rows, a page at a time, Prev / Next at the bottom right
local LIST_ROWS = math.floor((H - 80 - ROW_Y) / ROW_H)
local COL_W = math.floor((W - 48) / 2)
local PER_PAGE = 2 * LIST_ROWS
local function list_cell(k)
  return 16 + ((k - 1) // LIST_ROWS) * (COL_W + 16), ROW_Y + ((k - 1) % LIST_ROWS) * ROW_H
end
local function draw_list(gg, rows, page)
  local first = (page - 1) * PER_PAGE
  for k = 1, PER_PAGE do
    local r = rows[first + k]
    if not r then break end
    local x, y = list_cell(k)
    gg:text(x, y + 4, kit.short(r.label, 30), { font = kit.font('medium') })
    if r.sub and r.sub ~= '' then gg:text(x, y + 30, kit.short(r.sub, 36), { font = kit.font('small') }) end
    gg:rect(x, y + ROW_H - 2, COL_W, 1)
  end
end
local function list_hit(rows, page, x, y)
  if y < ROW_Y then return nil end
  local row = (y - ROW_Y) // ROW_H
  if row >= LIST_ROWS then return nil end
  local col = x < 16 + COL_W + 8 and 0 or 1
  return rows[(page - 1) * PER_PAGE + col * LIST_ROWS + row + 1]
end
local function page_buttons(btns, page, n, set_page)
  if page > 1 then btns[#btns + 1] = { x = W - 236, y = H - 66, w = 100, h = 50, label = 'Prev', fn = function() set_page(page - 1) end } end
  if page * PER_PAGE < n then btns[#btns + 1] = { x = W - 116, y = H - 66, w = 100, h = 50, label = 'Next', fn = function() set_page(page + 1) end } end
end
local function join(...)
  local t = {}
  for _k, s in ipairs({ ... }) do if s and s ~= '' then t[#t + 1] = s end end
  return table.concat(t, ' · ')
end

------------------------------------------------------------------ catalog screens

-- cat.view: 'levels' | 'composers' | 'pieces' | 'search' | 'piece'
local cat = { view = 'levels', page = 1 }

local function cat_msg(s) cat.msg = s; refresh_now() end

local function open_catalog()
  screen, cat = 'catalog', { view = 'levels', page = 1, msg = 'Loading the catalog …' }
  C.refresh(function(ok, err)
    cat.msg = (not ok) and (err .. (C.loaded() and ' (showing the list from last time)' or '')) or nil
    refresh_now()
  end)
end

local function show_card(entry)
  cat.back, cat.view, cat.id, cat.msg = { view = cat.view, page = cat.page }, 'piece', entry.id, nil
end

-- the rows of the current list view: { label, sub, fn }
local function cat_rows()
  local rows = {}
  if cat.view == 'levels' then
    for _k, l in ipairs(C.levels()) do
      rows[#rows + 1] = { label = l.label .. ' (' .. l.count .. ')', fn = function() cat.view, cat.level, cat.page = 'composers', l.level, 1 end }
    end
  elseif cat.view == 'composers' then
    for _k, c in ipairs(C.composers(cat.level)) do
      rows[#rows + 1] = { label = c, fn = function() cat.view, cat.composer, cat.page = 'pieces', c, 1 end }
    end
  elseif cat.view == 'pieces' or cat.view == 'search' then
    local list = cat.view == 'pieces' and C.pieces(cat.level, cat.composer) or C.search(cat.query)
    for _k, p in ipairs(list) do
      rows[#rows + 1] = { label = p.title, sub = join(cat.view == 'search' and p.composer or nil, C.installed(p.id) and 'downloaded' or nil),
                          fn = function() show_card(p) end }
    end
  end
  return rows
end

local function search()
  ctx.input:text({ title = 'Search the catalog (title or composer)' }, function(_c, text)
    if text and text ~= '' then cat.view, cat.query, cat.page = 'search', text, 1 end
    refresh_now()
  end)
end

local function cat_buttons()
  local btns, y = {}, H - 66
  if cat.view == 'piece' then
    local e = C.get(cat.id)
    if not e then return btns end
    if C.installed(e.id) then
      btns[#btns + 1] = { x = 16, y = 330, w = 214, h = 50, label = 'Open', fn = function() open_piece({ name = C.file(e.id) }) end }
    else
      btns[#btns + 1] = { x = 16, y = 330, w = 214, h = 50, label = 'Download', fn = function()
        cat_msg('Downloading …')
        C.download(e.id, function(ok, err) cat_msg(ok and 'Downloaded.' or err) end)
      end }
    end
    return btns
  end
  if cat.view == 'levels' then btns[#btns + 1] = { x = 16, y = y, w = 214, h = 50, label = 'Search', fn = search } end
  page_buttons(btns, cat.page, #cat_rows(), function(p) cat.page = p end)
  return btns
end

local TITLES = { levels = 'Catalog', composers = 'Composers', pieces = 'Pieces', search = 'Search' }

local function draw_catalog(gg)
  if cat.view == 'piece' then
    local e = C.get(cat.id)
    if e then
      local y = 20
      for _k, l in ipairs(kit.wrap(e.title, 'large', W - 32)) do gg:text(16, y, l, { font = kit.font('large') }); y = y + 36 end
      local lines = {}
      local function add(l) if l and l ~= '' then lines[#lines + 1] = l end end
      add(e.composer)
      if e.arranger and e.arranger ~= '' then add('arranged by ' .. e.arranger) end
      add(join(e.level, e.pages and (e.pages .. ' pages') or nil, e.size and (math.ceil(e.size / 1024) .. ' KB') or nil))
      if e.license then add('License: ' .. e.license) end
      if e.source then add('Source: ' .. e.source) end
      for _k, l in ipairs(lines) do
        for _j, w in ipairs(kit.wrap(l, 'small', W - 32)) do gg:text(16, y + 6, w, { font = small() }); y = y + 26 end
      end
    end
  else
    local title = TITLES[cat.view]
    if cat.view == 'composers' then title = cat.level and (cat.level:sub(1, 1):upper() .. cat.level:sub(2)) or '' end
    if cat.view == 'pieces' then title = cat.composer end
    if cat.view == 'search' then title = 'Search: ' .. (cat.query or '') end
    gg:text(16, 20, kit.short(title or '', 30), { font = kit.font('large') })
    local rows = cat_rows()
    draw_list(gg, rows, cat.page)
    if #rows == 0 and not cat.msg then gg:text(16, ROW_Y, cat.view == 'search' and 'Nothing found.' or 'Nothing here yet.', { font = small() }) end
  end
  if cat.msg then for k, l in ipairs(kit.wrap(cat.msg, 'small', W - 32)) do gg:text(16, (cat.view == 'piece' and 400 or 70) + (k - 1) * 22, l, { font = small() }) end end
  for _k, b in ipairs(cat_buttons()) do kit.button(gg, b.x, b.y, b.w, b.h, b.label) end
end

local function tap_catalog(x, y)
  for _k, b in ipairs(cat_buttons()) do
    if x >= b.x and x < b.x + b.w and y >= b.y and y < b.y + b.h then b.fn(); return end
  end
  if cat.view == 'piece' then return end
  local r = list_hit(cat_rows(), cat.page, x, y)
  if r then cat.msg = nil; r.fn() end
end

local function back_catalog()
  if cat.view == 'piece' then cat.view, cat.page = cat.back.view, cat.back.page; cat.msg = nil
  elseif cat.view == 'pieces' then cat.view, cat.page = 'composers', 1
  elseif cat.view == 'composers' or cat.view == 'search' then cat.view, cat.page = 'levels', 1
  else go_home() end
end

local function home_rows()
  local rows = {}
  for _k, row in ipairs(pieces) do
    rows[#rows + 1] = { label = row.title, sub = row.bad and 'cannot be opened' or join(row.composer, row.level), fn = function() open_piece(row) end }
  end
  return rows
end
local function home_buttons()
  local btns = { { x = 16, y = H - 66, w = 214, h = 50, label = 'Catalog', fn = open_catalog },
                 { x = 250, y = H - 66, w = 214, h = 50, label = 'Keyboard', fn = function() screen = 'keyboard'; K.auto() end } }
  page_buttons(btns, home_page, #pieces, function(p) home_page = p end)
  return btns
end

local NAMES = { 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B' }
local function note_name(n) return NAMES[n % 12 + 1] .. (n // 12 - 1) end

-- the keyboard screen: state, Search / Forget, the keyboards found
local function keyboard_buttons()
  local btns = {}
  if ctx.ble then
    btns[#btns + 1] = { x = 16, y = 150, w = 214, h = 48, label = 'Search', fn = K.scan }
    btns[#btns + 1] = { x = 250, y = 150, w = 214, h = 48, label = 'Forget', fn = K.forget }
    for k, d in ipairs(K.devices()) do                     -- two columns of three
      if k > 6 then break end
      btns[#btns + 1] = { x = 16 + ((k - 1) // 3) * (COL_W + 16), y = 250 + ((k - 1) % 3) * 56, w = COL_W, h = 48,
                          label = d.name or d.address, fn = function() K.pick(k) end }
    end
  end
  return btns
end

local KB_TEXT = { off = 'This reader has no Bluetooth: turn the pages by hand.', none = 'Not connected. Turn the keyboard on and search.',
                  scanning = 'Searching for Bluetooth MIDI keyboards …', connecting = 'Connecting …', lost = 'Keyboard lost: trying again …' }

local function draw_keyboard(gg)
  gg:text(16, 20, 'Keyboard', { font = kit.font('large') })
  local st = K.state()
  local line = st == 'connected' and ('Connected: ' .. (K.name() or 'keyboard')) or KB_TEXT[st] or st
  for k, l in ipairs(kit.wrap(line, 'medium', W - 32)) do gg:text(16, 66 + (k - 1) * 28, l, { font = medium() }) end
  if K.last() then gg:text(16, 214, 'Last note: ' .. note_name(K.last()), { font = small() }) end
  for _k, b in ipairs(keyboard_buttons()) do kit.button(gg, b.x, b.y, b.w, b.h, b.label, { font = 'medium' }) end
end

local function draw_home(gg)
  gg:text(16, 14, 'Piano Follow', { font = kit.font('large') })
  gg:text(16, 70, 'My pieces', { font = medium() })
  if #pieces == 0 then
    for k, l in ipairs(kit.wrap('No pieces yet. Download some from the catalog, or convert your own on the website and copy them to ' .. ctx.files.path .. '.', 'small', W - 32)) do
      gg:text(16, ROW_Y + (k - 1) * 24, l, { font = small() })
    end
  end
  draw_list(gg, home_rows(), home_page)
  for _k, b in ipairs(home_buttons()) do kit.button(gg, b.x, b.y, b.w, b.h, b.label) end
end

local function draw_markers(gg)
  if cur.mode == 'follow' and cur.fst and cur.fst.bar then
    local b = cur.map.bars[cur.fst.bar]
    if b and b[1] == cur.page then
      -- dashed and a little apart, so it does not read as a staff or ledger line
      local y = BAR_H + b[3] + 12
      for x = b[2], b[2] + b[4] - 8, 14 do gg:rect(x, y, 8, 3, { fill = true }) end
    end
  elseif cur.mode == 'practice' and cur.pst and not cur.pst.done then
    local o = cur.map.onsets[cur.pst.pos]
    -- under the system the note is in, at the height of Follow's line: never inside the music
    local b = o and cur.map.bars[o[2]]
    if o and b and o[3] == cur.page then gg:rect(o[4] - 6, BAR_H + b[3] + 10, 12, 5, { fill = true }) end
  end
end

local function draw_score(gg)
  gg:text(8, 8, K.state() == 'lost' and 'Keyboard lost' or kit.short(cur.p.header.title, 28), { font = small() })
  local ml = mode_label()
  if ml then gg:text(MODE_X() + math.floor((MODE_W - kit.width(small(), ml)) / 2), 8, ml, { font = small() }); gg:rect(MODE_X(), 3, MODE_W, BAR_H - 8) end
  local right = cur.page .. '/' .. cur.pages
  if cur.mode == 'practice' and cur.pst and cur.pst.wrong > 0 then right = 'Wrong ' .. cur.pst.wrong .. '  ' .. right end
  gg:text(SW() - 8 - kit.width(small(), right), 8, right, { font = small() })
  gg:rect(0, BAR_H - 2, SW(), 1)
  if layer then gg:image(layer, 0, BAR_H) end
  draw_markers(gg)
end

-- the practice summary: buttons laid out once for drawing and tapping
local function summary_buttons()
  local s = P.summary(cur.pst)
  local btns, rows = {}, 3                                  -- two columns of three bars on the wide screen
  for k, b in ipairs(s.bars) do
    if k > 2 * rows then break end
    local x, y = 16 + ((k - 1) // rows) * (COL_W + 16), 150 + ((k - 1) % rows) * 56
    btns[#btns + 1] = { x = x + 150, y = y, w = COL_W - 150, h = 44, label = 'Practice from bar ' .. b.bar, text = 'Bar ' .. b.bar .. ': ' .. b.wrong .. ' wrong',
                        tx = x, fn = function() start_mode(first_onset_of(2, b.bar)); screen = 'score' end }
  end
  local y = 150 + rows * 56 + 20
  btns[#btns + 1] = { x = 16, y = y, w = 214, h = 48, label = 'Again', fn = function() start_mode(1); screen = 'score' end }
  btns[#btns + 1] = { x = 250, y = y, w = 214, h = 48, label = 'Back to the score', fn = function() screen = 'score' end }
  return s, btns, math.max(0, #s.bars - 2 * rows)
end

local function draw_summary(gg)
  local s, btns, more = summary_buttons()
  gg:text(16, 20, 'Practice done', { font = kit.font('large') })
  gg:text(16, 70, s.wrong == 0 and 'No wrong notes.' or ('Wrong notes: ' .. s.wrong), { font = medium() })
  if #s.bars > 0 then gg:text(16, 110, 'Bars to practise:', { font = small() }) end
  if more > 0 then gg:text(500, 110, '+' .. more .. ' more bars', { font = small() }) end
  for _k, b in ipairs(btns) do
    if b.text then gg:text(b.tx, b.y + 10, b.text, { font = small() }) end
    kit.button(gg, b.x, b.y, b.w, b.h, b.label, { font = 'small' })
  end
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    if screen == 'score' and cur then draw_score(gg)
    elseif screen == 'summary' and cur then draw_summary(gg)
    elseif screen == 'keyboard' then draw_keyboard(gg)
    elseif screen == 'catalog' then draw_catalog(gg)
    else draw_home(gg) end
    if kit.modal() then kit.draw_modal(gg) end
    if ERR then gg:text(12, H - 24, kit.short('ERR ' .. ERR, 48), { font = small() }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function inside(b, x, y) return x >= b.x and x < b.x + b.w and y >= b.y and y < b.y + b.h end

local function tap_home(x, y)
  for _k, b in ipairs(home_buttons()) do if inside(b, x, y) then b.fn(); return end end
  local r = list_hit(home_rows(), home_page, x, y)
  if r then r.fn() end
end

local function tap_keyboard(x, y)
  for _k, b in ipairs(keyboard_buttons()) do if inside(b, x, y) then b.fn(); return end end
end

local function tap_score(x, y)
  if y < BAR_H then
    if x >= MODE_X() and x < MODE_X() + MODE_W then mode_menu() end
    return
  end
  if x < SW() / 3 then turn_by_hand(cur.page - 1)
  elseif x > SW() * 2 / 3 then turn_by_hand(cur.page + 1) end
end

local function tap_summary(x, y)
  local _s, btns = summary_buttons()
  for _k, b in ipairs(btns) do if inside(b, x, y) then b.fn(); return end end
end

local function key_score(k)
  if k == 'left' or k == 'up' then turn_by_hand(cur.page - 1); return true end
  if k == 'right' or k == 'down' then turn_by_hand(cur.page + 1); return true end
  return false
end

function on_input(c, ev)
  local handled, redraw = true, false
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' then
      if ev.phase == 'up' then
        ERR = nil
        redraw = true
        local x, y = ev.x or 0, ev.y or 0
        if kit.modal() then kit.tap_modal(x, y)
        elseif screen == 'score' then tap_score(x, y)
        elseif screen == 'summary' then tap_summary(x, y)
        elseif screen == 'keyboard' then tap_keyboard(x, y)
        elseif screen == 'catalog' then tap_catalog(x, y)
        else tap_home(x, y) end
      end
    elseif ev.type == 'key' and ev.phase ~= 'down' then
      redraw = true
      if ev.key == 'back' then
        if kit.modal() then kit.close()
        elseif screen == 'summary' then screen = 'score'
        elseif screen == 'catalog' then back_catalog()
        elseif screen == 'score' or screen == 'keyboard' then go_home()
        else handled, redraw = false, false end            -- the host asks whether to leave
      elseif screen == 'score' and not kit.modal() then
        redraw = key_score(ev.key)
      else
        redraw = false
      end
    end
  end)
  if not ok then ERR = tostring(e); redraw = true end
  if redraw then refresh_now() end
  return handled
end

function on_load(c)
  local ok, e = pcall(function()
    local kv = kit.kv(kit.read('settings.txt'))
    if kv.turn_at == 'system' or kv.turn_at == 'bar' then settings.turn_at = kv.turn_at end
    go_home()
    K.start(on_midi, function() request(300) end)
  end)
  if not ok then ERR = tostring(e) end
end
function on_leave() pcall(save_piece) end

if rawget(_G, '__TEST') then
  go_home_for_test = function() go_home() end
  piece_key_for_test = piece_key
  __TEST.api = { pieces = function() return pieces end, S = S, M = M, F = F, P = P, screen = function() return screen end, cur = function() return cur end,
                 mode_label = mode_label, practice = function() return cur and cur.pst end }
end
